package com.nexusdrive.storage.service;import com.nexusdrive.storage.config.StorageProperties;import java.util.concurrent.CompletableFuture;import org.slf4j.*;import org.springframework.http.MediaType;import org.springframework.scheduling.annotation.Async;import org.springframework.stereotype.Service;import org.springframework.web.client.RestClient;@Service public class ReplicationService{private static final Logger log=LoggerFactory.getLogger(ReplicationService.class);private final StorageProperties p;private final RestClient http=RestClient.create();public ReplicationService(StorageProperties p){this.p=p;}@Async public CompletableFuture<Void> replicate(String id,byte[] data){int needed=Math.max(0,p.getReplicationFactor()-1);p.getPeers().stream().limit(needed).forEach(peer->{try{retry(()->{http.put().uri(url(peer)+"/chunks/{id}",id).header("X-Storage-Secret",p.getInternalSecret()).header("X-Replication-Request","true").contentType(MediaType.APPLICATION_OCTET_STREAM).body(data).retrieve().toBodilessEntity();});}catch(Exception e){log.error("Replication of {} to {} failed after retries",id,peer,e);}});return CompletableFuture.completedFuture(null);}@Async public void deleteReplicas(String id){p.getPeers().forEach(peer->{try{retry(()->http.delete().uri(url(peer)+"/chunks/{id}",id).header("X-Storage-Secret",p.getInternalSecret()).header("X-Replication-Request","true").retrieve().toBodilessEntity());}catch(Exception e){log.warn("Replica deletion of {} at {} failed after retries",id,peer);}});}private void retry(Runnable op){RuntimeException last=null;for(int i=0;i<5;i++){try{op.run();return;}catch(RuntimeException e){last=e;try{Thread.sleep(200L*(1L<<i));}catch(InterruptedException x){Thread.currentThread().interrupt();throw last;}}}throw last;}private String url(String peer){return peer.startsWith("http")?peer:"http://"+peer;}}
